//! Independent 257-parent distributed literal referee for D15 R4-2.
mod audit {
#![allow(dead_code,unused_imports)]
include!("../unaudited-codex-orbit0-hidden-k16-children-prefix-2026-08-23/run_hidden_children_prefix.rs");
const INPUT:&str="computations/unaudited-codex-orbit0-filtered-k16-run-2026-08-23/checkpoint_direct_k15.bin";
const OUT:&str="computations/unaudited-codex-orbit0-k21-d15-r4-2-charge-2026-08-24/results_k21_d15_r4_2_samples.json";
const TSV:&str="computations/unaudited-codex-orbit0-k21-d15-r4-2-charge-2026-08-24/results_k21_d15_r4_2_samples.tsv";
const N:u64=5_311_211;
fn rec(data:&[u8],i:usize)->(Row,i64){let o=16+32*i;let mut x=[0;24];x.copy_from_slice(&data[o..o+24]);(Row(x),i64::from_le_bytes(data[o+24..o+32].try_into().unwrap()))}
fn hex(r:&Row)->String{r.0.iter().map(|x|format!("{:02x}",x)).collect()}
pub fn run(){let begun=Instant::now();let data=read(INPUT).unwrap();assert_eq!(&data[..8],b"K15CHK1\0");assert_eq!(u64::from_le_bytes(data[8..16].try_into().unwrap()),N);assert_eq!(data.len(),16+32*N as usize);let e=parse();let c=cenv();assert!(e.pivots.iter().all(|p|p.iter().map(|&x|x as usize).sum::<usize>()==4));let ids=(0..257).map(|j|j*(N-1)/256).collect::<Vec<_>>();assert_eq!((ids[0],ids[256]),(0,N-1));assert!(ids.windows(2).all(|x|x[0]<x[1]));let mut lines=vec!["input_index\trow\tweight\tm1\tp1_uses\tK4_candidates\tpivotable_K19\tp2_uses\tK21_children\tcharge_scaled_U".to_string()];let(mut p1n,mut k4n,mut k19n,mut p2n,mut k21n,mut charge,mut guards)=(0u64,0u64,0u64,0u64,0u64,0i128,0u64);
 for &ii in &ids{let(row,v)=rec(&data,ii as usize);let s15=signature(&row.0,&e);assert_eq!(s15.iter().map(|&x|x as usize).sum::<usize>(),9);let ps1=available(s15,&e);let m1=ps1.len();assert!(m1>0);let mut q=[0i128;6];q[0]=m1 as i128;q[1]=(60*m1)as i128;for p1 in ps1{let w19=-(v as i128)*U/(m1 as i128);assert_eq!((v as i128)*U%(m1 as i128),0);for t4 in &c.k4[p1]{assert_eq!(tail_signature(t4,&e).iter().map(|&x|x as usize).sum::<usize>(),0);let s19=child_sig(s15,p1,t4,&e);assert_eq!(s19.iter().map(|&x|x as usize).sum::<usize>(),5);let ps2=available(s19,&e);if ps2.is_empty(){continue}q[2]+=1;let m2=ps2.len();assert_eq!(U%((m1*m2)as i128),0);assert_eq!(w19%(m2 as i128),0);let w21=-w19/(m2 as i128);let row19=replace_anchor(&row,&e.anchors[p1],t4);assert_eq!(signature(&row19.0,&e),s19);for p2 in ps2{q[3]+=1;let prof=path_profile(&row19,p2,&e,&c);for t2 in &e.all_k2[p2]{let s21=child_sig(s19,p2,t2,&e);assert_eq!(s21.iter().map(|&x|x as usize).sum::<usize>(),3);assert!(available(s21,&e).is_empty());let row21=replace_anchor(&row19,&e.anchors[p2],t2);assert_eq!(signature(&row21.0,&e),s21);let a=abstract_ckey(&prof,p2,t2,&e,&c);let l=literal_ckey(&row21,&c);assert_eq!(a,l);q[4]+=1;q[5]+=w21*(*c.dual.get(&l).unwrap_or(&0)as i128);guards+=1}}}}
  p1n+=q[0]as u64;k4n+=q[1]as u64;k19n+=q[2]as u64;p2n+=q[3]as u64;k21n+=q[4]as u64;charge+=q[5];lines.push(format!("{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}",ii,hex(&row),v,m1,q[0],q[1],q[2],q[3],q[4],q[5]));
 }
 assert_eq!(lines.len(),258);assert_eq!(k4n,60*p1n);assert_eq!(k21n,12*p2n);assert_eq!(guards,k21n);std::fs::write(TSV,format!("{}\n",lines.join("\n"))).unwrap();let text=format!("{{\n  \"status\":\"PASS_INDEPENDENT_257_LITERAL_D15_R4_2_K21_SAMPLES\",\n  \"strict_covered_lineage_ids\":[\"D15:223|R:4-2\",\"D15:232|R:4-2\",\"D15:322|R:4-2\"],\n  \"parents\":257,\n  \"first_index\":0,\n  \"last_index\":{},\n  \"p1_uses\":{},\n  \"K4_candidates\":{},\n  \"pivotable_K19_children\":{},\n  \"p2_uses\":{},\n  \"K21_children\":{},\n  \"charge_scaled_U\":\"{}\",\n  \"literal_abstract_cycle_key_guards\":{},\n  \"all_K21_terminal\":true,\n  \"elapsed_seconds\":{:.6}\n}}\n",N-1,p1n,k4n,k19n,p2n,k21n,charge,guards,begun.elapsed().as_secs_f64());std::fs::write(OUT,&text).unwrap();print!("{}",text)}
}
fn main(){audit::run()}
